const getPricingDetails = async () => {
  return await browserjs(tabId, () => {
    // get all text inside the Azure OpenAI card or section
    const card = document.querySelector('.calculator');
    // Let's find the inputs, prices, labels
    const rows = Array.from(document.querySelectorAll('.row, .calculator-row, [class*="detail"]')).map(r => r.innerText);
    // Also let's find all text around tokens
    const textNodes = [];
    const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    while (node = walk.nextNode()) {
      if (node.textContent.includes('$') || node.textContent.includes('tokens') || node.textContent.includes('Input') || node.textContent.includes('Output')) {
        textNodes.push(node.textContent.trim());
      }
    }
    return {
      textNodes: textNodes.filter(t => t.length > 0)
    };
  });
};

