const checkRatesForModel = async (modelVal) => {
  return await browserjs(tabId, (mVal) => {
    const select = document.querySelector('select[name="modelForLanguage"]');
    select.value = mVal;
    select.dispatchEvent(new Event('change', { bubbles: true }));

    // Give a moment or read immediately
    const textNodes = [];
    const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    while (node = walk.nextNode()) {
      if (node.textContent.includes('Per 1,000 tokens')) {
        textNodes.push({
          parent: node.parentElement?.innerText,
          grandparent: node.parentElement?.parentElement?.innerText
        });
      }
    }
    return {
      model: select.options[select.selectedIndex].text,
      textNodes
    };
  }, modelVal);
};

