const parsePricingTables = await browserjs(tabId, async () => {
  const resp = await fetch('https://azure.microsoft.com/en-us/pricing/details/azure-openai/');
  const html = await resp.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');

  // Find tables or headings mentioning Data Zones, GPT-4o, etc.
  const tables = Array.from(doc.querySelectorAll('table')).map(table => {
    const rows = Array.from(table.querySelectorAll('tr')).map(tr => 
      Array.from(tr.querySelectorAll('th, td')).map(cell => cell.textContent.trim())
    );
    return rows;
  });

  const headings = Array.from(doc.querySelectorAll('h2, h3, h4')).map(h => h.textContent.trim());

  // Filter tables that mention GPT-4o
  const gptTables = tables.filter(t => 
    t.some(row => row.some(cell => cell.includes('GPT-4o') || cell.includes('gpt-4o')))
  );

  return { headings, gptTablesCount: gptTables.length, gptTables };
});

