const modules = await browserjs(tabId, () => {
  // Let's find all Azure OpenAI instances
  const selects = Array.from(document.querySelectorAll('select[name="modelForLanguage"]'));
  return selects.map((s, idx) => {
    // Find the container
    let container = s;
    while (container && !container.classList.contains('row-module') && !container.classList.contains('calculator-module') && container.parentElement !== document.body) {
      container = container.parentElement;
    }
    return {
      index: idx,
      modelSelected: s.options[s.selectedIndex]?.text,
      modelValue: s.value,
      region: container ? container.querySelector('select[name="region"]')?.value : null,
      deploymentType: container ? container.querySelector('select[name="deploymentType"]')?.value : null,
      strategy: container ? container.querySelector('select[name="pricingStrategy"]')?.value : null
    };
  });
});

