const pricingData = await browserjs(tabId, async () => {
  const resp = await fetch('https://azure.microsoft.com/en-us/pricing/details/azure-openai/');
  const html = await resp.text();

  // Search for JSON or scripts containing pricing or data zones
  const matches = [];
  const scriptRegex = /<script[^>]*>([\s\S]*?)<\/script>/gi;
  let match;
  while ((match = scriptRegex.exec(html)) !== null) {
    if (match[1].includes('GPT-4o') || match[1].includes('gpt-4o') || match[1].includes('Data Zones')) {
      matches.push(match[1].slice(0, 500));
    }
  }

  // Also check if there is an API URL or data attribute
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const tables = Array.from(doc.querySelectorAll('table[data-amount]'));

  return {
    scriptsFound: matches.length,
    matches: matches.slice(0, 5),
    tablesWithData: tables.length
  };
});

