const moduleDetails = await browserjs(tabId, () => {
  const selects = Array.from(document.querySelectorAll('select[name="modelForLanguage"]'));
  return selects.map((s, idx) => {
    // Find ancestor module
    let container = s;
    while (container && !container.classList.contains('module') && !container.classList.contains('calculator-module') && container.parentElement !== document.body) {
      if (container.parentElement && container.parentElement.classList.contains('calculator')) break;
      container = container.parentElement;
    }
    const inputs = Array.from(container.querySelectorAll('input[type="text"], input[type="number"], .numeric-value, spinbutton')).map(i => ({
      name: i.name,
      value: i.value,
      ariaLabel: i.getAttribute('aria-label')
    }));
    return {
      index: idx,
      model: s.options[s.selectedIndex]?.text,
      containerTag: container.tagName,
      className: container.className,
      inputs
    };
  });
});

console.log("Module details:", JSON.stringify(moduleDetails, null, 2));

