const costs = await browserjs(tabId, () => {
  // Let's get the estimate summary
  const upfrontText = document.querySelector('.total-row .upfront-cost, [class*="upfront"]')?.textContent;
  const monthlyText = document.querySelector('.total-row .monthly-cost, [class*="monthly"]')?.textContent;

  // Let's grab all text elements in the estimate section
  const summary = {
    modules: []
  };

  const moduleNodes = document.querySelectorAll('.module, .calculator-module, [data-row-id]');

  // Also let's inspect the cost summary lines in the document
  const costLines = [];
  const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while (node = walk.nextNode()) {
    const text = node.textContent.trim();
    if (text.includes('$') || text.includes('cost') || text.includes('Cost') || text.includes('Estimate') || text.includes('Total')) {
      costLines.push(text);
    }
  }

  return {
    costLines: costLines.filter(c => c.length > 0)
  };
});

