const currentBreakdown = await browserjs(tabId, () => {
  // Let's find all text blocks for module 1 and 2
  const results = [];
  const selects = Array.from(document.querySelectorAll('select[name="modelForLanguage"]'));
  selects.forEach((s, idx) => {
    let container = s;
    while (container && !container.classList.contains('module') && container.parentElement !== document.body) {
      if (container.parentElement && container.parentElement.classList.contains('calculator')) break;
      container = container.parentElement;
    }
    results.push({
      model: s.options[s.selectedIndex]?.text,
      text: container ? container.innerText : ""
    });
  });

  // Total costs
  const upfront = document.querySelector('.total-row .upfront-cost, [class*="upfront"]')?.parentElement?.innerText;
  const monthly = document.querySelector('.total-row .monthly-cost, [class*="monthly"]')?.parentElement?.innerText;

  return {
    results,
    upfront,
    monthly,
    totalMonthlyEstimate: document.querySelector('.estimated-monthly-cost')?.textContent || document.querySelector('.total-monthly-cost')?.textContent
  };
});

